head.script:
scwin.tData = {
    "description" : "[multiselect > E > onrowclick]<br/>MultiSelect 컴포넌트의 아이템을 클릭했을 때 발생합니다.",
    "validation" : [
        "accessibility=true 상태에서는 키보드의 Space 또는 Enter 키를 이용하여 아이템 행을 선택할 때에도 onrowclick 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



scwin.target1_onrowclick = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1 onrowclick =====");
    wf_body_bottom.getObj("scwin").setReturnValue("info: " + JSON.stringify(info));
};



// comp 생성 (accessibility=true 적용)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cList = $c.gcm.createCList({ accessibility: "true" });
    let eList = $c.gcm.createEList(["onrowclick"]);

    await $c.gcm.createBasicMultiSelect(cList, eList);
}
